#include <vector>
#include <algorithm>

class Solution {
public:
    int maxTwoNonOverlappingSquaresArea(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<int>> dp(m, std::vector<int>(n, 0));
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1) {
                    if (r == 0 || c == 0) dp[r][c] = 1;
                    else dp[r][c] = std::min({dp[r - 1][c], dp[r][c - 1], dp[r - 1][c - 1]}) + 1;
                }
            }
        }
        std::vector<int> rowPref(m, 0);
        int curMx = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) curMx = std::max(curMx, dp[r][c] * dp[r][c]);
            rowPref[r] = curMx;
        }
        std::vector<int> rowSuff(m, 0);
        curMx = 0;
        for (int r = m - 1; r >= 0; --r) {
            for (int c = 0; c < n; ++c) {
                for (int candR = r; candR < m; ++candR) {
                    int sz = std::min(dp[candR][c], candR - r + 1);
                    curMx = std::max(curMx, sz * sz);
                }
            }
            rowSuff[r] = curMx;
        }
        int best = 0;
        for (int r = 0; r < m - 1; ++r) {
            best = std::max(best, rowPref[r] + rowSuff[r + 1]);
        }
        return best;
    }
};

class Solution {
    public int maxTwoNonOverlappingSquaresArea(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] dp = new int[m][n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    if (r == 0 || c == 0) dp[r][c] = 1;
                    else dp[r][c] = Math.min(dp[r - 1][c], Math.min(dp[r][c - 1], dp[r - 1][c - 1])) + 1;
                }
            }
        }
        int[] rowPref = new int[m];
        int curMx = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) curMx = Math.max(curMx, dp[r][c] * dp[r][c]);
            rowPref[r] = curMx;
        }
        int[] rowSuff = new int[m];
        curMx = 0;
        for (int r = m - 1; r >= 0; r--) {
            for (int c = 0; c < n; c++) {
                for (int candR = r; candR < m; candR++) {
                    int sz = Math.min(dp[candR][c], candR - r + 1);
                    curMx = Math.max(curMx, sz * sz);
                }
            }
            rowSuff[r] = curMx;
        }
        int best = 0;
        for (int r = 0; r < m - 1; r++) {
            best = Math.max(best, rowPref[r] + rowSuff[r + 1]);
        }
        return best;
    }
}

